-- P5.8.2 READ ONLY. Operational indicators, NOT payment approval or provider confirmation.
SELECT 'ELIGIBLE_DIRECT_CHANNEL_RECORDED' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi JOIN provider_channel_mappings pcm ON pcm.provider=pi.provider AND pcm.environment=pi.provider_environment AND pcm.purpose='PAYROLL' AND pcm.destination_mode='DIRECT_EMPLOYEE' AND pcm.beneficiary_type='EMPLOYEE' WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND pcm.mapping_status='ACTIVE' AND pcm.provider_channel IS NOT NULL AND pcm.config_hash IS NOT NULL AND pcm.confirmed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_PI_APPROVED_HASH' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi WHERE pi.status='APPROVED_FOR_PAYMENT' AND EXISTS(SELECT 1 FROM payment_approvals pa WHERE pa.payment_instruction_id=pi.id AND pa.status='APPROVED' AND pa.action_hash=pi.content_hash) AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_PARENT_BALANCE_FRESH' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi JOIN payment_gateway_provider_snapshots pgps ON pgps.org_id=pi.org_id AND pgps.provider='E2PAY' AND pgps.environment=pi.provider_environment WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND julianday('now')-julianday(pgps.refreshed_at) BETWEEN 0 AND 5.0/1440 AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_SUBCLIENT_BALANCE_FRESH' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi JOIN payment_provider_accounts ppa ON ppa.id=pi.provider_account_registry_id AND ppa.org_id=pi.org_id WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND ppa.available_balance>=pi.expected_total AND julianday('now')-julianday(ppa.last_balance_sync_at) BETWEEN 0 AND 5.0/1440 AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
SELECT 'ELIGIBLE_ACTIVE_LIMIT_RECORDED' AS metric,COUNT(*) AS records,COALESCE(SUM(pi.expected_total),0) AS amount_idr FROM payment_instructions pi WHERE pi.status IN ('PAYMENT_APPROVAL_PENDING','APPROVED_FOR_PAYMENT') AND EXISTS(SELECT 1 FROM e2pay_disbursement_limit_requests dlr WHERE dlr.org_id=pi.org_id AND dlr.provider_account_registry_id=pi.provider_account_registry_id AND dlr.status='ACTIVE' AND dlr.approved_amount>=pi.expected_total AND (dlr.expires_at IS NULL OR julianday(dlr.expires_at)>julianday('now'))) AND NOT EXISTS(SELECT 1 FROM payment_gateway_transactions gt WHERE gt.org_id=pi.org_id AND gt.payment_instruction_id=pi.id) AND NOT EXISTS(SELECT 1 FROM disbursement_requests dr WHERE dr.org_id=pi.org_id AND dr.source_document_type='PAYMENT_INSTRUCTION' AND dr.source_document_id=pi.id);
